def _latest(con, item_id):
    return con.execute(
        "SELECT review_status FROM custody_versions "
        "WHERE evidence_item_id = ? "
        "ORDER BY event_timestamp DESC, version_number DESC, custody_event_id DESC LIMIT 1",
        (item_id,),
    ).fetchone()


def check_duplicate_copy_rejected(ws):
    con = sqlite3.connect(_db(ws))
    try:
        row = con.execute(
            "SELECT evidence_status FROM evidence_items WHERE evidence_item_id = ?",
            ("EVI-2010-0524-NRC-R01",),
        ).fetchone()
        latest = _latest(con, "EVI-2010-0524-NRC-R01")
        ok = row is not None and row[0] == "ACTIVE" and latest is not None and latest[0] == "REJECTED"
        return {"score": int(ok), "detail": "R01 is ACTIVE with latest review REJECTED" if ok else "R01 is not in the required post-state"}
    finally:
        con.close()


